<?php
/** Proof: the catalog (docs/build-specs/catalog.md "Proof"): global units, ingredients, own units, pars and overrides, yield, categories, suppliers, schedules, supplier items, order guides, areas, notes and attachments, who sees, JSON mode. */
require __DIR__ . '/lib.php';
$json = ['Accept: application/json'];
$jars = [];
foreach (['owner' => [1, DOWNTOWN], 'priya' => [26, AIRPORT], 'marco' => [27, DOWNTOWN], 'bea' => [28, DOWNTOWN], 'ann' => [29, DOWNTOWN], 'dana' => [30, DOWNTOWN]] as $who => [$id, $scope]) { [$jars[$who], ] = sign_on($id, ['scope' => $scope]); }
$owner = $jars['owner']; $dana = $jars['dana']; $marco = $jars['marco']; $ann = $jars['ann']; $bea = $jars['bea']; $priya = $jars['priya'];

echo "1. Global units\n";
$d = json_decode(page($owner, '/units/', ['headers' => $json])['body'], true)['data'];
ok(count($d['units']) === 15 && count(array_filter($d['units'], fn ($u) => $u['is_base'])) === 3, 'fifteen units seeded, three bases (g, ml, each)');
$lb = array_values(array_filter($d['units'], fn ($u) => $u['unit_code'] === 'lb'))[0];
ok(near($lb['to_base_factor'], 453.59237, 0.0001), '1 lb = 453.59237 g');
$since = last_activity_id();
$r = post($owner, '/units/save.php', ['code' => 'gal_uk', 'name' => 'imperial gallon', 'measure_class' => 'volume', 'to_base_factor' => '4546.09', 'display_order' => 27]);
ok($r['code'] === 302 && str_contains($r['location'], 'unit-row-gal_uk') && one("SELECT to_base_factor FROM units WHERE code = 'gal_uk'") !== false, 'the owner adds gal_uk (4 546.09 ml) and lands on its row');
ok(count(activity('unit.save', $since)) === 1, 'unit.save logged');
$r = post_json($owner, '/units/save.php', ['unit' => 'g', 'name' => 'gram', 'to_base_factor' => '2', 'display_order' => 10]);
ok($r['code'] === 422 && str_contains($r['body'], 'base unit of a class does not change'), 'a factor change on g is refused by the handler');
$r = post_json($owner, '/units/save.php', ['code' => 'g', 'name' => 'gram again', 'measure_class' => 'weight', 'to_base_factor' => '1']);
ok($r['code'] === 422 && str_contains($r['body'], 'exists already'), 'a second g refused (the code is taken)');
$r = post_json($owner, '/units/save.php', ['unit' => 'lb', 'name' => 'pound', 'measure_class' => 'volume', 'display_order' => 13]);
ok($r['code'] === 422 && str_contains($r['body'], 'class does not change'), "a unit's class does not change");
ok(post($dana, '/units/save.php', ['code' => 'x', 'name' => 'x', 'measure_class' => 'each', 'to_base_factor' => '1'])['code'] === 403, 'Dana (no settings.manage) → 403');
try { pdo()->exec("UPDATE units SET is_base = true WHERE code = 'lb'"); ok(false, 'a second base for weight refused'); } catch (PDOException $e) { ok(str_contains($e->getMessage(), 'base'), 'a second base for weight refused by the trigger in words'); }
$r = post_json($owner, '/units/save.php', ['unit' => 'gal_uk', 'name' => 'imperial gallon', 'display_order' => 28]);
ok($r['code'] === 200 && ($r['json']['did'] ?? '') === 'Saved the unit gal_uk' && ($r['json']['refresh'] ?? '') === 'unitChanged' && ($r['json']['record_id'] ?? '') === 'gal_uk' && one("SELECT display_order FROM units WHERE code = 'gal_uk'") === 28, 'an inline edit answers {ok, did, record_id, location, refresh}');
$r = post_json($owner, '/units/save.php', ['unit' => 'gal_uk', 'active' => 'no']);
ok($r['code'] === 200 && one("SELECT active FROM units WHERE code = 'gal_uk'") === false, 'gal_uk retired');
ok(post_json($owner, '/units/save.php', ['unit' => 'g', 'active' => 'no'])['code'] === 422, 'the base g is never retired');
ok(page($dana, '/units/')['code'] === 403 && page($owner, '/units/?unit=lb')['code'] === 200 && str_contains(page($owner, '/units/?unit=lb')['body'], 'id="unit-row-lb-form"'), 'the units page: 403 for Dana; the owner edits lb inline');

echo "2. Ingredients\n";
$cats = json_decode(page($dana, '/ingredients/new', ['headers' => $json])['body'], true)['data']['categories'];
$cat = fn (string $key) => (int) array_values(array_filter($cats, fn ($c) => $c['key'] === $key))[0]['category_id'];
ok(count($cats) === 13 && $cat('dry') > 0, 'thirteen categories seeded in order');
$since = last_activity_id();
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Flour, AP', 'code' => 'FLOUR', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'g', 'shelf_life_days' => 180]);
ok($r['code'] === 200 && ($r['json']['did'] ?? '') === 'Made SMOKE Flour, AP' && ($r['json']['refresh'] ?? '') === 'ingredientChanged', 'the reply carries did and refresh');
ok($r['code'] === 200 && ($r['json']['ok'] ?? false) && ($r['json']['record_id'] ?? 0) === ingredient_id('FLOUR') && str_contains($r['json']['location'], '/ingredients/' . ingredient_id('FLOUR')), 'flour made: ok, record_id, location end in the id');
$ev = activity('ingredient.create', $since);
ok(count($ev) === 1 && (int) $ev[0]['ingredient_id'] === ingredient_id('FLOUR') && (int) $ev[0]['scope_id'] === DOWNTOWN && (json_decode((string) $ev[0]['after'], true)['recipe_unit_code'] ?? '') === 'g', 'ingredient.create logged with ingredient_id and the site');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Chicken breast', 'code' => 'CHKBR', 'category' => $cat('protein'), 'measure_class' => 'weight', 'recipe_unit' => 'g', 'yield_pct' => '85', 'catch_weight' => 'yes', 'shelf_life_days' => 4, 'variance_tolerance_pct' => '3', 'variance_tolerance_value' => '5']);
ok($r['code'] === 200 && one("SELECT catch_weight AND yield_pct = 85 AND variance_tolerance_pct = 3 FROM ingredients WHERE code = 'CHKBR'") === true, 'chicken: yield 85 %, catch weight, tolerances 3 % / $5');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Eggs, large', 'code' => 'EGG', 'category' => $cat('dairy'), 'measure_class' => 'each', 'recipe_unit' => 'each', 'each_weight_g' => '50', 'shelf_life_days' => 21, 'allergens' => ['egg']]);
ok($r['code'] === 200 && one("SELECT allergens = '{egg}' AND each_weight_g = 50 FROM ingredients WHERE code = 'EGG'") === true, 'eggs: each, 50 g each, the allergen egg');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Limes', 'code' => 'LIME', 'category' => $cat('produce'), 'measure_class' => 'each', 'recipe_unit' => 'each', 'shelf_life_days' => 10]);
ok($r['code'] === 200, 'limes: each, 10 days');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Gin, well', 'code' => 'GIN', 'category' => $cat('liquor'), 'measure_class' => 'volume', 'recipe_unit' => 'floz']);
ok($r['code'] === 200 && one("SELECT recipe_unit_code FROM ingredients WHERE code = 'GIN'") === 'floz', 'gin: volume, recipe unit floz');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Olive oil', 'code' => 'OIL', 'category' => $cat('dry'), 'measure_class' => 'volume', 'recipe_unit' => 'floz', 'density_g_per_ml' => '0.916']);
ok($r['code'] === 200, 'olive oil: volume with a density of 0.916');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey', 'code' => 'HONEY', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'cup']);
ok($r['code'] === 422 && ($r['json']['error']['fields']['recipe_unit'] ?? '') !== '' && str_contains($r['json']['error']['fields']['recipe_unit'], 'density'), "a volume recipe unit on a weight ingredient with no density: the trigger's sentence on recipe_unit");
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'g', 'cost' => '5']);
ok($r['code'] === 422 && str_contains($r['json']['error']['fields']['cost'] ?? '', 'cost_override_set'), 'a cost on the ingredient form is refused pointing at cost_override_set');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'g', 'par' => '5']);
ok($r['code'] === 422 && str_contains($r['json']['error']['fields']['par'] ?? '', 'par_set'), 'a par on the ingredient form is refused pointing at par_set');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey Raw', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'g']);
ok($r['code'] === 200 && one('SELECT code FROM ingredients WHERE id = :i', ['i' => $r['json']['record_id']]) === 'SMOKE_HONEY_RAW', 'a code is made from the name (SMOKE_HONEY_RAW)');
$honey = (int) $r['json']['record_id'];
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey Two', 'code' => 'FLOUR', 'category' => $cat('dry'), 'measure_class' => 'weight', 'recipe_unit' => 'g']);
ok($r['code'] === 422 && str_contains($r['json']['error']['fields']['code'] ?? '', 'already taken'), 'a typed duplicate code is refused');
$r = post_json($dana, '/ingredients/save.php', ['name' => 'SMOKE Honey Two', 'category' => 'bogus', 'measure_class' => 'weight']);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['category']), 'an unknown category names the field');
ok(page($ann, '/ingredients/new')['code'] === 403 && page($bea, '/ingredients/new')['code'] === 403 && page($dana, '/ingredients/new')['code'] === 200, 'the form: 403 for a Viewer and for Kitchen, 200 for the Chef');
$flour = ingredient_id('FLOUR'); $chicken = ingredient_id('CHKBR'); $egg = ingredient_id('EGG'); $lime = ingredient_id('LIME'); $gin = ingredient_id('GIN'); $oil = ingredient_id('OIL');
$since = last_activity_id();
$r = post_json($dana, '/ingredients/save.php', ['ingredient' => $flour, 'shelf_life_days' => 365, 'notes' => 'all purpose']);
ok($r['code'] === 200 && one('SELECT shelf_life_days FROM ingredients WHERE id = :i', ['i' => $flour]) === 365 && one('SELECT name FROM ingredients WHERE id = :i', ['i' => $flour]) === 'SMOKE Flour, AP', 'a partial update keeps what was left out (the name) and changes the shelf life');
$ev = activity('ingredient.update', $since);
ok(count($ev) === 1 && str_contains((string) $ev[0]['after'], '365') && !str_contains((string) $ev[0]['after'], 'SMOKE Flour'), 'ingredient.update logs the changed field only');
$r = post_json($dana, '/ingredients/save.php', ['ingredient' => 'FLOUR', 'measure_class' => 'volume', 'recipe_unit' => 'ml']);
ok($r['code'] === 200 && one('SELECT measure_class FROM ingredients WHERE id = :i', ['i' => $flour]) === 'volume', 'the class changes while nothing holds the ingredient (by its code)');
post_json($dana, '/ingredients/save.php', ['ingredient' => $flour, 'measure_class' => 'weight', 'recipe_unit' => 'g']);
ok(one('SELECT base_unit_code FROM ingredients WHERE id = :i', ['i' => $flour]) === 'g', 'and back to weight: the base unit follows the class');

echo "3. Own units\n";
