$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $flour, 'unit_code' => 'bag50', 'name' => '50 lb bag', 'kind' => 'purchase', 'holds_qty' => '50', 'holds_unit' => 'lb', 'is_default_count' => 'yes']);
ok($r['code'] === 200 && near($r['json']['to_base_factor'] ?? null, 22679.6185, 0.001) && str_contains($r['json']['sentence'] ?? '', '1 bag50 = 22,679.6185 g') && str_contains($r['json']['location'], 'ingredient-unit-row-'), '"holds 50 lb" → to_base_factor 22 679.6185 and the sentence "1 bag50 = 22,679.6185 g"');
$ev = activity('ingredient.unit_set', $since);
ok(count($ev) === 1 && (int) $ev[0]['ingredient_id'] === $flour && str_contains((string) $ev[0]['after'], 'bag50'), 'ingredient.unit_set logged with ingredient_id');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit_code' => 'case', 'name' => 'case of 15 dozen', 'kind' => 'purchase', 'holds_qty' => '180', 'holds_unit' => 'each', 'is_default_count' => 'yes']);
ok($r['code'] === 200 && near($r['json']['to_base_factor'], 180, 0.0001), 'a case of eggs = 180 each');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit_code' => 'flat', 'name' => 'flat of 30', 'kind' => 'count', 'holds_qty' => '30', 'holds_unit' => 'each', 'is_default_count' => 'yes']);
ok($r['code'] === 200 && one("SELECT unit_code FROM ingredient_units WHERE ingredient_id = :i AND is_default_count", ['i' => $egg]) === 'flat', 'a flat of 30 as the default count — the case loses the flag');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit_code' => 'case2', 'name' => 'half', 'kind' => 'purchase', 'holds_qty' => '0.5', 'holds_unit' => 'each']);
ok($r['code'] === 422 && str_contains($r['body'], 'never'), 'a case2 of 0.5 each refused: a case is never one each');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit_code' => 'lb', 'name' => 'pound', 'kind' => 'count', 'holds_qty' => '1', 'holds_unit' => 'each']);
ok($r['code'] === 422 && str_contains($r['body'], 'global unit'), 'a code lb refused: a global unit');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $lime, 'unit_code' => 'case', 'name' => 'case of 200', 'kind' => 'purchase', 'holds_qty' => '5', 'holds_unit' => 'g']);
ok($r['code'] === 422 && ($r['json']['error']['fields']['holds_unit'] ?? '') !== '' && str_contains($r['json']['error']['fields']['holds_unit'], 'each-weight'), 'limes in grams refused on holds_unit (no each-weight)');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $lime, 'unit_code' => 'case', 'name' => 'case of 200', 'kind' => 'purchase', 'holds_qty' => '200', 'holds_unit' => 'each', 'is_default_count' => 'yes']);
ok($r['code'] === 200, 'a case of 200 limes');
post_json($dana, '/ingredients/units/save.php', ['ingredient' => $gin, 'unit_code' => 'bottle', 'name' => '750 ml bottle', 'kind' => 'count', 'holds_qty' => '750', 'holds_unit' => 'ml', 'is_default_count' => 'yes']);
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $gin, 'unit_code' => 'case6', 'name' => 'case of 6', 'kind' => 'purchase', 'holds_qty' => '6', 'holds_unit' => 'bottle']);
ok($r['code'] === 200 && near($r['json']['to_base_factor'], 4500, 0.0001), 'a case of 6 bottles entered as 6 bottles = 4 500 ml (an own unit of an own unit)');
post_json($dana, '/ingredients/units/save.php', ['ingredient' => $chicken, 'unit_code' => 'case', 'name' => 'case, ~40 lb', 'kind' => 'purchase', 'holds_qty' => '40', 'holds_unit' => 'lb', 'is_default_count' => 'yes']);
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $oil, 'unit_code' => 'case4', 'name' => 'case of 4 × 1 gal', 'kind' => 'purchase', 'holds_qty' => '4', 'holds_unit' => 'gal', 'is_default_count' => 'yes']);
ok($r['code'] === 200 && near($r['json']['to_base_factor'], 15141.647, 0.01), 'a case of 4 gallons of oil = 15 141.6 ml');
$unitId = (int) one("SELECT id FROM ingredient_units WHERE ingredient_id = :i AND unit_code = 'case'", ['i' => $egg]);
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit' => $unitId, 'active' => 'no']);
ok($r['code'] === 200 && one('SELECT active FROM ingredient_units WHERE id = :u', ['u' => $unitId]) === false, 'the case of eggs retired');
$r = post_json($dana, '/ingredients/units/save.php', ['ingredient' => $egg, 'unit' => $unitId, 'active' => 'yes']);
ok($r['code'] === 200 && one('SELECT active FROM ingredient_units WHERE id = :u', ['u' => $unitId]) === true, 'and restored');
$h = page($dana, '/ingredients/' . $flour . '/units')['body'];
ok(str_contains($h, 'id="ingredient-units-table"') && str_contains($h, '1 bag50 = 22,679.6185 g') && str_contains($h, '1 lb = 453.5924 g'), "the units page shows the factor sentences of the own unit and the class's global units");
$d = json_decode(page($dana, '/ingredients/' . $oil, ['headers' => $json])['body'], true)['data'];
$lbOpt = null; foreach ($d['units'] as $u) { if ($u['unit_code'] === 'case4') { $lbOpt = $u; } }
ok($lbOpt !== null && near(one('SELECT ri_to_base(:i, 1, \'lb\')', ['i' => $oil]), 495.19, 0.05), '1 lb of olive oil = 495 ml through the density');

echo "4. Pars and overrides\n";
$since = last_activity_id();
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => DOWNTOWN, 'par' => '250', 'par_unit' => 'kg', 'par_mode' => 'fixed']);
ok($r['code'] === 200 && near(one('SELECT par_base FROM ingredient_site_settings WHERE ingredient_id = :i AND scope_id = 101', ['i' => $flour]), 250000) && ($r['json']['par_mode'] ?? '') === 'fixed', "flour's par at Downtown: 250 kg → par_base 250 000");
$ev = activity('ingredient.par_set', $since);
ok(count($ev) === 1 && (int) $ev[0]['scope_id'] === DOWNTOWN && (int) $ev[0]['ingredient_id'] === $flour, 'ingredient.par_set logged with scope_id 101 and the ingredient');
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $egg, 'site' => DOWNTOWN, 'par_mode' => 'dynamic', 'service_level' => '0.950']);
ok($r['code'] === 200 && one("SELECT par_mode || ':' || service_level FROM ingredient_site_settings WHERE ingredient_id = :i AND scope_id = 101", ['i' => $egg]) === 'dynamic:0.950', 'eggs dynamic at 95 %');
ok(post_json($priya, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => AIRPORT, 'par' => '1', 'par_unit' => 'kg'])['code'] === 403, 'Priya (Kitchen at Airport) → 403');
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => AIRPORT, 'par' => '1', 'par_unit' => 'kg']);
ok($r['code'] === 404, 'Dana (Chef at Downtown only) at Airport → 404 (not a site she holds)');
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => 999, 'par' => '1', 'par_unit' => 'kg']);
ok($r['code'] === 404, 'a site not held → 404');
// areas for the default-area checks (the owner makes them — the areas section proves them)
post_json($owner, '/areas/save.php', ['name' => 'SMOKE Walk-in', 'kind' => 'walk_in', 'walk_order' => 1]);
post_json($owner, '/areas/save.php', ['name' => 'SMOKE Dry store', 'kind' => 'dry', 'walk_order' => 2]);
post_json($owner, '/areas/save.php', ['name' => 'SMOKE Bar', 'kind' => 'bar', 'walk_order' => 3]);
post_json($owner, '/switch-site.php', ['site' => AIRPORT]);
post_json($owner, '/areas/save.php', ['name' => 'SMOKE Walk-in', 'kind' => 'walk_in', 'walk_order' => 1]);
post_json($owner, '/switch-site.php', ['site' => DOWNTOWN]);
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => DOWNTOWN, 'default_area' => area_id(AIRPORT, 'SMOKE Walk-in')]);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['default_area']), "an area of Airport refused as Downtown's default");
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => DOWNTOWN, 'default_area' => area_id(DOWNTOWN, 'SMOKE Dry store')]);
ok($r['code'] === 200 && (int) one('SELECT default_area_id FROM ingredient_site_settings WHERE ingredient_id = :i AND scope_id = 101', ['i' => $flour]) === area_id(DOWNTOWN, 'SMOKE Dry store'), 'the dry store as the default area');
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => DOWNTOWN, 'preferred_supplier_item' => 'LATER']);
ok($r['code'] === 422 && str_contains($r['json']['error']['fields']['preferred_supplier_item'] ?? '', 'does not sell'), 'a preferred supplier item that is not one of this ingredient\'s refused in words');
$r = post_json($dana, '/ingredients/sites/save.php', ['ingredient' => $flour, 'site' => DOWNTOWN, 'reorder_min' => '100', 'reorder_min_unit' => 'kg']);
ok($r['code'] === 200 && near(one('SELECT reorder_min_base FROM ingredient_site_settings WHERE ingredient_id = :i AND scope_id = 101', ['i' => $flour]), 100000), 'a reorder minimum of 100 kg → 100 000 g');
$d = json_decode(page($dana, '/ingredients/' . $flour . '/sites', ['headers' => $json])['body'], true)['data'];
ok(count($d['rows'] ?? $d['sites'] ?? []) >= 1, 'the sites page answers JSON with a row per held site');
// cost override
