$ev = activity('ingredient.cost_override', $since);
ok(count($ev) === 1 && (int) $ev[0]['scope_id'] === DOWNTOWN, 'ingredient.cost_override logged with scope_id');
ok(post_json($dana, '/ingredients/sites/cost.php', ['ingredient' => $chicken, 'site' => DOWNTOWN, 'cost' => '1', 'unit' => 'lb'])['code'] === 403, 'Dana (Chef, no prices.write) → 403');
$r = post_json($marco, '/ingredients/sites/cost.php', ['ingredient' => $chicken, 'site' => AIRPORT, 'cost' => '1', 'unit' => 'lb']);
ok($r['code'] === 403, 'Marco at Airport (Kitchen there, no prices.write, no cost) → 403');
