echo "5. Yield\n";
$r = req('POST', '/ingredients/yield-tests/save.php', ['jar' => $dana, 'form' => ['ingredient' => $chicken, 'ap_qty' => '2500', 'ap_qty_unit' => 'g', 'ep_qty' => '1750', 'ep_qty_unit' => 'g', 'preview' => '1', 'csrf_token' => page_csrf($dana)]]);
